from journal.features.workers.support.plan_approval import PlanApproval
from journal.support.option import USER, Option
from journal.support.option_scope import OptionScope


MERGER_TESTING = "Hand the tests over"
WORKER_TESTING = "Run the tests it wrote"
TEST_BUDGET = "Test budget"
JOURNAL_TESTING = "The journal runs them"


class WorkersOptions:
    TIMEOUT = Option("workers.timeout_minutes", "Time limit of a worker run", "Minutes a worker may run before it is stopped and its report states that it was; 0 sets no limit", 60, unit="min")
    MODE = Option("workers.mode", "Work mode", "Builder: the agent builds it itself and sends workers when a job is better done beside it. Orchestrator: it plans, hands the work to workers, then reviews and merges it. Solo: it does everything itself, with no workers", "builder", kind="choice", choices=("builder", "orchestrator", "solo"), scope=OptionScope.PERSON, setter=USER)
    REVIEWER_LIMIT = Option("workers.reviewers_most", "Reviewers: most out", "The most reviewers out at once, apart from the workers: the review queue adds a reviewer while reviews wait and fewer than this are out; they do not count toward the worker limits", 2, unit="reviewers")
    VERIFIER_LIMIT = Option("workers.verifiers_most", "Verifiers: most out", "The most verifiers out at once, apart from the workers: a verdict wanted past it waits for one to come free; they do not count toward the worker limits", 2, unit="verifiers")
    CODE_SHARE_FULL = Option("workers.own_share_full_score", "Fitness: share of its own code at full score", "In builder mode, the share of the code landed in the window that the builder wrote itself, against the lines merged from its workers, from which the fitness is whole", 0.67, unit="ratio")
    CODE_SHARE_ZERO = Option("workers.own_share_zero_score", "Fitness: share of its own code at no score", "In builder mode, the share of its own code at or under which that part of the fitness scores nothing", 0.33, unit="ratio")
    CODE_SHARE_WEIGHT = Option("workers.own_share_weight", "Fitness: weight of the share of its own code", "How much the builder's share of its own code weighs among the measures of its fitness; the file edits weigh 3", 4, unit="weight")
    BUILDER_HANDOVER_LINES = Option("workers.builder_lines_per_handover", "Builder: lines of its own per handover", "The lines the builder writes itself since its last handover that one worker or queued task out is worth; a handover under it sends the agent a line at once to write the next piece itself; 0 never sends it", 50, unit="lines")
    BUILDER_DISPATCH_ALLOWED = Option("workers.builder_may_dispatch", "Builder may dispatch workers", "On: in builder mode the agent may dispatch a worker with journal worker dispatch. Off: the line is refused", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    BUILDER_QUEUE_ALLOWED = Option("workers.builder_may_queue", "Builder may queue a worker's next task", "On: in builder mode the agent may queue a worker's next task with journal worker queue. Off: the line is refused", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    BUILDER_SUBAGENTS_ALLOWED = Option("workers.builder_may_subagents", "Builder may send subagents", "On: in builder mode the agent may send its program's own subagents. Off: the dispatch is refused", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    SOLO_SUBAGENTS_ALLOWED = Option("workers.solo_may_subagents", "Solo may send subagents to help it", "On: in solo mode the agent may send its program's own subagents to help it. Off: the dispatch is refused", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_WRITES_PLANS = Option("workers.orchestrator_writes_plans", "Orchestrator may write plans", "On: in orchestrator mode the orchestrator drafts plans with journal plan create. Off: only you write a plan", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_RELEASES = Option("workers.orchestrator_releases", "Orchestrator may release", "On: in orchestrator mode the orchestrator may tag a version and publish a release. Off: a git tag or gh release line waits for you", False, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_APPROVES_PLANS = Option("workers.orchestrator_approves_plans", "Orchestrator approves plans", "On: in orchestrator mode the orchestrator approves a plan itself with journal plan approve, as the Plans option the orchestrator may approve describes. Off: only you approve a plan", False, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_PLAN_APPROVAL = Option("workers.orchestrator_plan_approval", "Plans the orchestrator may approve", "With Orchestrator approves plans on, the plans it may approve itself: only the plans it created, the plans you created, or all of them; you approve the rest", PlanApproval.OWN.value, kind="choice", choices=tuple(approval.value for approval in PlanApproval), scope=OptionScope.PERSON, setter=USER)
    BUILDER_HANDOVER_LIMIT = Option("workers.builder_handovers", "Builder: remind after handovers in a row", "Handovers to workers with no code edit of the builder's own between them, after which it is reminded to take the next task itself; 0 never reminds", 2, unit="handovers")
    ORCHESTRATOR_LINE_LIMIT = Option("workers.orchestrator_lines", "Orchestrator: remind after lines of its own code", "Lines of code the orchestrator changes itself since its last handover, after which it is reminded to hand the work to a worker; 0 never reminds", 200, unit="lines")
    PLAN_STALL_MINUTES = Option("workers.plan_stall_minutes", "Orchestrator: started plan stalled after", "Minutes a started plan may go without progress while another started plan moves, after which the orchestrator is informed once; 0 never informs it", 60, unit="min")
    FITNESS_THRESHOLD = Option("workers.fitness_threshold", "Lowest fitness before the measures off the ideal are listed", "The fitness score, from 0 to 100, against the ideal agent of its work mode, below which the agent sees its score and the measures furthest off the ideal; 0 turns this off", 70, unit="points")
    SOLO_DISPATCH_LIMIT = Option("workers.solo_dispatches", "Solo: remind after subagents over its own research", "Subagent dispatches beyond the solo agent's own reads and searches, among its last 50 tool uses, after which it is reminded to research itself; 0 never reminds", 3, unit="dispatches")
    CHECK_REMINDER_USES = Option("workers.check_reminder_uses", "Name work to check every", "Tool uses between the reminders, while the agent works on, of a worker's work that waits to be checked and merged", 25, unit="tool uses")
    TESTING = Option("workers.testing", "How workers test", "Hand the tests over: a worker never runs a test or the suite, each proof lists the test and the command that runs it, and the agent that merges runs them. Run the tests it wrote: a worker runs the tests it wrote, by name, never the full suite. Test budget: a worker tests only through journal tests turn, which allows its runs a turn within the budget below; a worker whose program has hooks has any other test run refused with that line, and a worker whose program has none receives the line alone. The journal runs them: a worker lists the tests that prove its work when it clocks out, the journal runs the test command with them in its worktree, and only a passing run lets the clock-out stand; a failing one goes back to the worker with its failing lines, and no worker is sent while the test command is not set", JOURNAL_TESTING, kind="choice", choices=(JOURNAL_TESTING, MERGER_TESTING, WORKER_TESTING, TEST_BUDGET))
    TEST_RUNS = Option("workers.test_runs", "Test runs at once", "With the test budget, the most test runs going at a time across all workers; a worker's run waits for its turn", 3, unit="runs")
    TEST_WAITING = Option("workers.test_waiting", "Turns that may wait", "With the test budget, the most turns that may wait for a free run; blank is no limit", "", kind="text", unit="turns")
    TEST_ID_LIMIT = Option("workers.tests_per_run", "Test ids in one run", "With the test budget, the most test ids one run may name", 20, unit="ids")
    TEST_RUN_MINUTES = Option("workers.test_run_minutes", "Minutes a test run may take", "With the test budget, the minutes after which a run is stopped", 10, unit="min")
    TEST_COMMAND = Option("workers.test_command", "Test command", "With the test budget or the journal running the tests, the command a turn runs with the test ids the worker lists; blank runs pytest where the project has a tests folder, and where it has none a turn is refused", "", kind="text")
    TEST_COMMAND_PROOF = Option("workers.test_command_proof", "Test command proved with", "The arguments of the passing run that proved the test command when it was set with journal tests command", "", kind="text")
    FAILING_RUNS = Option("workers.failing_runs", "Failing runs in a row", "With the test budget, the failing runs in a row of one worker after which the agent that sent it is informed, once, until a passed run starts the count again", 3, unit="runs")
    TEST_RUN_LINES = Option("workers.test_run_lines", "Line for each failed test run", "With the test budget, the agent that sent a worker is informed in one line of each of its test runs that failed, and how many failed; off, it is informed only once a worker keeps failing", True, kind="switch")
    WORKLOAD_WINDOW_MINUTES = Option("workers.load_window_minutes", "Load: minutes measured over", "In orchestrator mode, the sliding window the arrivals, the clearings and the wait from arrival to clearing are measured over", 30, unit="min")
    WORKLOAD_SMOOTHING_MINUTES = Option("workers.load_half_life_minutes", "Load: half-life of the smoothing", "The minutes after which a measure of the load weighs half as much in the smoothed load", 10, unit="min")
    SERIES_HOURS = Option("workers.series_hours", "Measures: hours of history stored", "How many hours of lines written, committed and merged, and of first reports, the agent's row stores for the measures to read", 3, unit="hours")
    COMMIT_LINE_CAP = Option("workers.commit_line_cap", "Measures: most lines a commit counts", "The most lines one commit counts toward the agent's own committed lines, so a reformat of a whole file weighs no more than a large change", 400, unit="lines")
    WORKLOAD_WARNING_RATIO = Option("workers.load_warn", "Load: warn at", "The load, arrivals over clearings, from which the status bar shows it as a warning", 0.7, unit="ratio")
    WORKLOAD_CRITICAL_RATIO = Option("workers.load_critical", "Load: critical at", "The load from which the status bar shows it as critical", 0.9, unit="ratio")
    BUILDER_CEILING = Option("workers.builder_load_ceiling", "Load: builder warned over", "The builder's own load, arrivals over clearings, from which the status bar shows it as a warning; lower is better", 0.5, unit="ratio")
    WORKLOAD_FIRST_NOTICE = Option("workers.load_told_from", "Load: first informed at", "The load, arrivals over clearings, at which the agent is first informed in one line what waits and what to clear first", 0.8, unit="ratio")
    WORKLOAD_NOTICE_STEP = Option("workers.load_told_step", "Load: informed again every", "The agent is informed again each time its load rises past another multiple of this above the first level; a fall lets the levels above be informed again", 0.05, unit="ratio")
    WORKLOAD_DRAIN_TOOL_USES = Option("workers.load_drain_tool_uses", "Load: drain line every", "Tool uses between the lines that ask the agent to drain its work, while its load is 1.0 or more", 25, unit="tool uses")
    PLACE_OPENING_RATIO = Option("workers.scale_up_at", "Load: add a place over", "The load that, held for the minutes below, opens one more place for a worker and a subagent, up to the ceiling", 0.8, unit="ratio")
    PLACE_CLOSING_RATIO = Option("workers.scale_down_at", "Load: remove a place under", "The load that, staying under for the minutes below, closes a place, down to the floor, never while a worker has a task or anything waits", 0.5, unit="ratio")
    PLACE_OPENING_MINUTES = Option("workers.scale_up_dwell_minutes", "Load: minutes over before a place opens", "How long the load stays over the level above before a place opens, and between two openings", 10, unit="min")
    PLACE_CLOSING_MINUTES = Option("workers.scale_down_dwell_minutes", "Load: minutes under before a place closes", "How long the load stays under the level above before a place closes, and between two closings", 20, unit="min")
    MIN_PLACES = Option("workers.place_floor", "Load: fewest worker places", "The fewest workers out at once the load may bring the limit down to; blank, the load never changes the places", "", kind="text", unit="places", setter=USER)
    MAX_PLACES = Option("workers.place_ceiling", "Load: most worker places", "The most workers out at once the load may bring the limit up to; blank, the load never changes the places", "", kind="text", unit="places", setter=USER)
    WEIGHT_USER_MESSAGE = Option("workers.weight_user_message", "Load: weight of a user message", "How much a message of the user's weighs in the load, a clock-out weighing 1", 3, unit="factor")
    RESEND_WEIGHT = Option("workers.weight_repeat_send_back", "Load: weight of a clock-out after a send-back", "How much a worker coming back after it was sent back weighs in the load", 1.5, unit="factor")
    WEIGHT_IDLE_PLACE = Option("workers.weight_idle_place", "Load: weight of an idle place", "How much an idle worker weighs in the load while a task is open", 0.5, unit="factor")
    RECOVERY_FULL = Option("workers.recovery_full_score_minutes", "Fitness: minutes over the load at full score", "Minutes the load may stay over the add-a-place level with the fitness still whole", 10, unit="min")
    RECOVERY_ZERO = Option("workers.recovery_zero_score_minutes", "Fitness: minutes over the load at no score", "Minutes over the add-a-place level at which that part of the fitness scores nothing", 60, unit="min")
    INTERRUPTION_WINDOW = Option("workers.interruption_window_minutes", "Fitness: minutes the worker reports are counted over", "The window over which the reports workers file to their dispatcher are counted against the work that was open for them", 60, unit="min")
    INTERRUPTIONS_FULL = Option("workers.interruptions_full_score_per_hour", "Fitness: worker reports an hour at full score", "Reports an hour, filed while plenty of work was open, that the fitness takes with no loss", 2, unit="reports an hour")
    INTERRUPTIONS_ZERO = Option("workers.interruptions_zero_score_per_hour", "Fitness: worker reports an hour at no score", "Reports an hour, filed while plenty of work was open, at which that part of the fitness scores nothing", 8, unit="reports an hour")
    PLENTY_OPEN = Option("workers.plenty_open_tasks", "Fitness: open tasks that are plenty of work", "Tasks open for workers at a report from which the report counts as an interruption: with fewer, a worker that reports had little else to take", 3, unit="tasks")
    QUICK_REPORT_MINUTES = Option("workers.quick_report_minutes", "Fitness: minutes after its job's start a report is quick", "A worker that reports within these minutes of its job's start while plenty of work is open costs the dispatcher a drop at once, whole within the first minute and falling to half at these minutes", 3, unit="min")
    QUICK_REPORT_DROP = Option("workers.quick_report_drop_points", "Fitness: points a quick report costs", "The points a quick report takes off the fitness at once", 20, unit="points")
    TINY_JOB_DROP = Option("workers.tiny_job_drop_points", "Fitness: points a job too small for a worker costs", "A worker that reports within a minute of its job's start while no other task is open did a job its dispatcher should have done itself, which takes these points off the fitness at once", 30, unit="points")
    DROP_RECOVERY_MINUTES = Option("workers.drop_recovery_minutes", "Fitness: minutes a drop takes to recover", "Minutes over which a quick report's drop wears off, falling straight to nothing", 30, unit="min")
    SMALL_TASK_POINTS = Option("workers.small_task_points", "Fitness: points of a small task", "A task whose brief has at most this many points is small: several small tasks to one worker fit --report queue", 2, unit="points")
    LARGE_TASK_POINTS = Option("workers.large_task_points", "Fitness: points of a large task", "A task whose brief has at least this many points is large: a long queue of large tasks fits --report every <n>", 5, unit="points")
    LONG_QUEUE_TASKS = Option("workers.long_queue_tasks", "Fitness: tasks in a long queue", "A worker with at least this many tasks sent to it has a long queue", 4, unit="tasks")
    MISFIT_DROP = Option("workers.report_misfit_drop_points", "Fitness: points a report choice far off costs", "The points a report choice that does not fit the work sent takes off the fitness at once", 10, unit="points")
    QUEUE_WINDOW = Option("workers.queue_window_minutes", "Fitness: minutes a worker's merges are counted over", "In orchestrator mode, the window over which each worker's merges give how fast its queue drains", 60, unit="min")
    QUEUE_DRAIN_HOURS = Option("workers.queue_drain_hours", "Fitness: hours of work a queue may hold", "In orchestrator mode, a worker whose queue contains more tasks than it drains in these hours is piling up", 2, unit="hours")
    COSTLY_SHAPED_WORK = Option("workers.costly_shaped_work_dollars", "Spend on the strongest model for settled work", "In orchestrator mode, the dollars a worker on the strongest model may spend on work its profile assigns a cheaper model before the orchestrator is informed, once, that a cheaper model may do it", 2.0, unit="dollars")
    STALLED_BLOCK_MINUTES = Option("workers.held_still_minutes", "Minutes blocked work may stand still", "In orchestrator mode, the minutes a blocked or paused task may go without a change before the orchestrator is informed the plan needs restructuring", 60, unit="min")
    BLOCKED_SHARE = Option("workers.held_share", "Share of tasks blocked or paused", "In orchestrator mode, the share of the tasks not done that may be blocked or paused before the orchestrator is informed the plan needs restructuring", 0.4, unit="ratio")
    UNORDERED_PLAN_TASKS = Option("workers.unordered_plan_tasks", "Open tasks of a plan with no dependencies", "In orchestrator mode, the open tasks of a started plan, none of them blocked on another, at which the orchestrator is asked which depend on which; 0 never asks", 10, unit="tasks")
    PRIORITIES_MINUTES = Option("workers.priorities_minutes", "Minutes between priority checks", "In orchestrator mode, the minutes after the orchestrator last gave a started plan's priorities before it is asked again which open task unblocks the most; a new phase asks at once; 0 asks only at a phase start", 45, unit="min")
    MODEL_FIT_SAMPLE = Option("workers.model_fit_sample", "Model fit: one merge in", "In orchestrator mode, one merge in this many is sampled by a verifier on the fast model, which judges whether the worker's model was too strong, right or too weak; 0 samples none", 5, unit="merges")
    WORKER_LIMIT = Option("workers.most_out", "Workers out at once", "The most workers out at a time; a dispatch past it is refused until one reports. 0 is no limit", 3, unit="workers")
    SUBAGENT_LIMIT = Option("workers.most_subagents", "Subagents running at once", "The most subagents running at a time; one more is held until one finishes. 0 is no limit", 5, unit="subagents")
    IDLE_HOURS = Option("workers.idle_hours", "Retire a resting worker after", "A worker with nothing out, nothing to check and nothing unmerged is retired after this many hours at rest, and its worktree removed, its last commit remaining; 0 never retires one", 4, unit="hours")
    MERGE_WINDOW_SECONDS = Option("workers.merge_window_seconds", "A plugin may pause a merge for", "Seconds a plugin that pauses a worker's merge, such as a judge of the whole tree, may take to answer; its own window in its manifest is cut to this, and the wait in the queue below is not counted", 180, unit="seconds")
    MERGE_LIMIT = Option("workers.merge_limit", "Merges asked about at once", "The most worker merges plugins are asked about at a time; a further merge waits until one is answered; 0 for no limit", 2, unit="merges")
    CLASH_LIMIT = Option("workers.clashes_named", "Clashes in a row before the dispatcher is informed", "How many times in a row a worker's branch is sent back to rebase because merges landed under it, after which the agent that sent it is informed so it can order the merges; 0 never informs", 3, unit="clashes")
    PROFILE_LIMIT = Option("workers.idle_kept", "Workers for reuse per profile", "The most workers of one profile out or idle for reuse; past it a dispatch of that profile is refused while one of them is idle, so the job goes to that one. Reviewers always start fresh. 0 is no limit", 8, unit="workers")
    WORKTREE_STEP = Option("workers.worktree_step", "Make worker worktrees the journal's way", "The journal makes a worker's worktree, a worktree of each inner repository it needs and its library folders; off, your own commands below make them, informed where in JOURNAL_WORKTREE and on which branch in JOURNAL_BRANCH", True, kind="switch", scope=OptionScope.MACHINE)
    PREPARATION_COMMANDS = Option("workers.preparation_commands", "Commands before a worker's worktree is made", "Your own shell commands, one per line, run in the project folder just before a worker's worktree is made; each receives JOURNAL_WORKTREE, JOURNAL_BRANCH, JOURNAL_PROJECT, JOURNAL_REPOSITORIES, JOURNAL_LIBRARIES and JOURNAL_COPIES", [], kind="lines", scope=OptionScope.MACHINE)
    BUILT_PATHS = Option("workers.built_paths", "Folders built from the sources", "Folders, one per line, that a build makes from the sources, such as a built viewer; a worker's merge that clashes only in them takes the project's side and builds them again with the command below", [], kind="lines")
    BUILD_COMMAND = Option("workers.build_command", "Command that builds them", "The shell command, run in the worker's worktree, that builds the folders above again after a merge clashed only in them", "", kind="text")
    POOL_SLOTS = Option("workers.pool_slots", "Worker slots for the team's pool", "How many workers this machine runs at once for teammates who dispatch to the team's pool; 0 offers none", 0, unit="workers", scope=OptionScope.MACHINE, setter=USER)
    POOL_MINUTES = Option("workers.pool_daily_minutes", "Minutes a day of pool work on this machine", "How many minutes a day this machine runs workers for teammates, counted from midnight; past it a pool worker is turned down until the next day. 0 sets no limit", 0, unit="min", scope=OptionScope.MACHINE, setter=USER)
    ALLOWED_MODELS = Option("workers.allowed_models", "Models each role may run on", "One line for each provider and role, such as claude journal-medior: sonnet, opus; the models a dispatch, a reviewer or a verifier of that role may run on, the minimum and the maximum being the ends of what is listed; one asking for another is moved to the nearest listed", ["claude journal-medior: sonnet, opus", "claude journal-senior: sonnet, opus", "claude reviewer: sonnet", "claude verifier: sonnet", "codex journal-medior: gpt-5.6-sol, gpt-6.1-sol, gpt-6-astra", "codex journal-senior: gpt-5.6-sol, gpt-6.1-sol, gpt-6-astra", "codex reviewer: gpt-5.6-sol, gpt-6.1-sol", "codex verifier: gpt-5.6-sol, gpt-6.1-sol"], kind="lines")
    POOL_PROFILES = Option("workers.pool_profiles", "Profiles a pool worker may use", "The worker profiles, one per line, a teammate may dispatch to the team's pool; a pool request naming another is refused", ["journal-medior"], kind="lines", setter=USER)
    COMPLETION_COMMANDS = Option("workers.completion_commands", "Commands after a worker's worktree is made", "Your own shell commands, one per line, run inside a worker's worktree once it is made, such as installing its dependencies; receiving the same values as the commands before", [], kind="lines", scope=OptionScope.MACHINE)
